/**
 * ENG-09 world-raster gate — SHARED test pattern.
 *
 * ONE deterministic, recognizable pattern, generated by ONE function, used
 * by BOTH fixtures in this directory:
 *
 *   index.js            mounts <world> and calls WorldRaster.setPixels with
 *                        this pattern as a raw RGBA buffer.
 *   reference-paths.js   decomposes the SAME visual pattern into COLS*ROWS
 *                        individual RNSVGPath rects -- the "how <world>'s
 *                        job used to be done" baseline the gate diffs
 *                        against.
 *
 * Sharing this function is the whole point: if the two fixtures computed
 * their tile colours independently, a luma match would only prove the two
 * generators agree, not that WorldRasterStore's bytes survived the
 * TurboModule -> store -> GL-texture -> DrawTextureRect round trip.
 *
 * COLS x ROWS = 17 x 14 = 238 tiles -- the same tile count as the
 * ~238-RNSVGPath decomposition this replaces (matches the 17-wedge count
 * already established by fixtures/p9-mark/index.js, times 14 rows). Each
 * tile gets a UNIQUE grayscale level on a ramp from 0 to 255, so the pattern
 * is a diagonal-reading gradient: instantly recognizable by eye (it is not a
 * flat fill or a 2-colour checkerboard, either of which a badly-broken
 * renderer could pass by accident), and it produces 238 distinct luma values
 * for the gate's histogram comparison -- a renderer that got the pattern
 * only approximately right (wrong tile boundaries, banding, a stuck
 * upload) moves the histogram in a way a same-flat-color pattern could not
 * reveal.
 */
'use strict';

const COLS = 17;
const ROWS = 14;
const TILE = 20; // px per tile, both axes
const WIDTH = COLS * TILE; // 340
const HEIGHT = ROWS * TILE; // 280

// Tile index i in [0, COLS*ROWS) -> a grayscale level in [0, 255], a linear
// ramp. Deterministic and pure so both fixtures (and the gate's own Python
// re-derivation, if it ever needs one) agree byte for byte.
function levelForTile(i) {
  return Math.round((i * 255) / (COLS * ROWS - 1));
}

function tileIndex(col, row) {
  return row * COLS + col;
}

module.exports = {COLS, ROWS, TILE, WIDTH, HEIGHT, levelForTile, tileIndex};
